//! The plugin's permissions (one per command, `permissions/autogenerated/`) and its Kotlin side
//! (`android/`: the native player, E6b-D1, and its output, E6b-D10), which Tauri's Android build
//! includes in the app's Gradle project.

/// The commands the page calls; the Kotlin plugin answers them (`PlayerPlugin.kt`), and the two
/// listener commands are Tauri's own, for the plugin's events.
const COMMANDS: &[&str] = &[
    "set_queue",
    "set_upcoming",
    "play",
    "pause",
    "seek",
    "stop",
    "status",
    "set_output",
    "output_info",
    "register_listener",
    "remove_listener",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).android_path("android").build();
}
